<?php
require __DIR__.'/lib.php';if(!defined('VICTOR_SHEET_TEST'))admin_init();
function sheet_reply(array $data,int $status=200): never {http_response_code($status);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);exit;}
function sheet_schema(PDO $db): void {$db->exec("CREATE TABLE IF NOT EXISTS order_sheet(code TEXT PRIMARY KEY,check_size TEXT NOT NULL DEFAULT '',shipping_created TEXT NOT NULL DEFAULT '',measurements TEXT NOT NULL DEFAULT '',tracking TEXT NOT NULL DEFAULT '',returned TEXT NOT NULL DEFAULT '');CREATE TABLE IF NOT EXISTS order_sheet_audit(id INTEGER PRIMARY KEY AUTOINCREMENT,code TEXT NOT NULL,actor TEXT NOT NULL,before_json TEXT NOT NULL,after_json TEXT NOT NULL,changed_at TEXT NOT NULL)");}
function sheet_rows(PDO $db,array $input): array {
 [$where,$params]=order_filters($input);$q=$db->prepare('SELECT count(*) FROM orders o'.$where);$q->execute($params);$total=(int)$q->fetchColumn();$page=max(1,min(max(1,(int)ceil($total/100)),(int)($input['page']??1)));
 $q=$db->prepare('SELECT o.*,n.number AS order_no,m.note AS admin_note,m.version AS admin_version,s.check_size,s.shipping_created,s.measurements,s.tracking,s.returned FROM orders o LEFT JOIN order_admin_numbers n ON n.code=o.code LEFT JOIN order_admin_meta m ON m.code=o.code LEFT JOIN order_sheet s ON s.code=o.code'.$where.' ORDER BY o.created_at DESC,o.code DESC LIMIT 100 OFFSET '.(($page-1)*100));$q->execute($params);$rows=[];
 foreach($q as $r){$o=admin_order($r);$rows[]=['code'=>$o['code'],'number'=>$o['number'],'version'=>$o['version'],'amount'=>$o['total']===null?'':(string)$o['total'],'customer'=>$o['customerName'],'phone'=>$o['phone'],'address'=>$o['address'],'products'=>implode(' + ',array_map(static fn($i)=>($i['sku']?:$i['name']).' '.($i['size']??'').((int)$i['qty']>1?' × '.$i['qty']:''),$o['items'])),'note'=>$o['note'],'check_size'=>$r['check_size']??'','shipping_created'=>$r['shipping_created']??'','measurements'=>$r['measurements']??trim(($o['height']?'Cao '.$o['height'].' cm ':'').($o['weight']?'Nặng '.$o['weight'].' kg':'')),'status'=>$o['status'],'tracking'=>$r['tracking']??'','returned'=>$r['returned']??'','createdAt'=>$o['createdAt']];}
 return ['rows'=>$rows,'total'=>$total,'page'=>$page,'pages'=>max(1,(int)ceil($total/100))];
}
function sheet_save(PDO $db,array $changes,string $actor): array {
 if(!array_is_list($changes)||!count($changes)||count($changes)>200)throw new RuntimeException('Lưu từ 1 đến 200 dòng mỗi lần.',400);
 $fields=['amount','customer','phone','address','products','note','check_size','shipping_created','measurements','status','tracking','returned'];$result=[];$seen=[];$db->beginTransaction();
 try{foreach($changes as $change){if(!is_array($change)||!is_array($change['values']??null))throw new RuntimeException('Dòng không hợp lệ.',400);$code=$change['code']??'';$new=$code==='';team_require($new?'create':'edit');if(!$new&&(!is_string($code)||!preg_match('/^TV-[A-F0-9]{12}$/D',$code)||isset($seen[$code])))throw new RuntimeException('Mã đơn không hợp lệ hoặc bị lặp.',400);$seen[$code]=true;$v=$change['values'];
 if(array_diff(array_keys($v),$fields))throw new RuntimeException('Cột không hợp lệ.',400);foreach($v as $key=>$value)if(!is_string($value)||mb_strlen($value)>($key==='address'||$key==='products'||$key==='note'?2000:200))throw new RuntimeException('Nội dung ô không hợp lệ hoặc quá dài.',400);
 $old=[];if(!$new){$q=$db->prepare('SELECT o.*,m.version AS admin_version,m.note AS admin_note FROM orders o LEFT JOIN order_admin_meta m ON m.code=o.code WHERE o.code=? AND NOT EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=o.code)');$q->execute([$code]);$old=$q->fetch();if(!$old)throw new RuntimeException('Đơn không còn trong danh sách. Hãy tải lại.',409);if(!is_int($change['version']??null)||(int)($old['admin_version']??0)!==$change['version'])throw new RuntimeException('Đơn '.$code.' vừa được người khác sửa. Chưa lưu dòng nào; hãy sao chép phần đang nhập rồi tải lại.',409);$payload=json_decode($old['payload'],true,512,JSON_THROW_ON_ERROR);$status=$old['status'];}else{$payload=['customerName'=>'','phone'=>'','address'=>'','note'=>'','items'=>[],'total'=>null,'shippingFee'=>0];$status='pending_confirmation';$code='TV-'.strtoupper(bin2hex(random_bytes(6)));}
 foreach(['customer'=>'customerName','phone'=>'phone','address'=>'address','note'=>'note'] as $key=>$target)if(array_key_exists($key,$v))$payload[$target]=trim($v[$key]);
 if(array_key_exists('amount',$v)){$amount=trim($v['amount']);if($amount!==''&&!preg_match('/^[0-9]{1,10}$/D',$amount))throw new RuntimeException('Tiền cần là số nguyên không âm, tối đa 10 chữ số.',400);$payload['total']=$amount===''?null:(int)$amount;}
 if(isset($v['products'])){$text=trim($v['products']);if($text==='')throw new RuntimeException('Cần nhập sản phẩm / size.',400);$payload['items']=[['sku'=>'','name'=>$text,'size'=>'','qty'=>1,'price'=>$payload['total'],'color'=>'']];}
 if($payload['customerName']===''||$payload['address']===''||!preg_match('/^(?:0[0-9]{9}|\+84[0-9]{9})$/D',$payload['phone'])||!count($payload['items']))throw new RuntimeException('Cần tên khách, SĐT hợp lệ (giữ số 0 đầu), địa chỉ và sản phẩm.',400);
 if(isset($v['status'])){if(!isset(ADMIN_STATUSES[$v['status']]))throw new RuntimeException('Tình trạng không hợp lệ.',400);$status=$v['status'];}
 $now=gmdate('Y-m-d\TH:i:s\Z');$json=json_encode($payload,JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR);
 if($new){$db->prepare('INSERT INTO orders(code,owner,request_key,created_at,status,payload,ip_hash) VALUES(?,?,?,?,?,?,?)')->execute([$code,'admin:'.$actor,bin2hex(random_bytes(16)),$now,$status,$json,'manual']);$db->prepare('INSERT INTO order_sources(code,source,channel) VALUES(?,?,?)')->execute([$code,'offline','phone']);$db->prepare('INSERT INTO order_admin_numbers(code) VALUES(?)')->execute([$code]);}else $db->prepare('UPDATE orders SET status=?,payload=? WHERE code=?')->execute([$status,$json,$code]);
 $version=(int)($old['admin_version']??0)+1;$db->prepare('INSERT INTO order_admin_meta(code,note,version,updated_at) VALUES(?,?,?,?) ON CONFLICT(code) DO UPDATE SET version=excluded.version,updated_at=excluded.updated_at')->execute([$code,$old['admin_note']??'',$version,$now]);
 $db->prepare('INSERT OR IGNORE INTO order_sheet(code) VALUES(?)')->execute([$code]);foreach(['check_size','shipping_created','measurements','tracking','returned'] as $key)if(array_key_exists($key,$v))$db->prepare('UPDATE order_sheet SET '.$key.'=? WHERE code=?')->execute([trim($v[$key]),$code]);
 $db->prepare('INSERT INTO order_sheet_audit(code,actor,before_json,after_json,changed_at) VALUES(?,?,?,?,?)')->execute([$code,$actor,json_encode(['payload'=>$old['payload']??null,'status'=>$old['status']??null]),json_encode($v,JSON_UNESCAPED_UNICODE),$now]);$result[]=['code'=>$code,'version'=>$version];}
 $db->commit();return $result;}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}
}
if(defined('VICTOR_SHEET_TEST'))return;
try{
 if(!admin_logged_in())throw new RuntimeException('Vui lòng đăng nhập lại.',401);$identity=team_identity();$method=$_SERVER['REQUEST_METHOD'];
 if($method==='GET'){team_require('view');$action=$_GET['action']??'';if($action==='users')sheet_reply(['users'=>team_users(),'rights'=>TEAM_RIGHTS]);$db=admin_db();sheet_schema($db);if($action==='history'){team_require('edit');$q=$db->prepare('SELECT actor,after_json,changed_at FROM order_sheet_audit WHERE code=? ORDER BY id DESC LIMIT 50');$q->execute([(string)($_GET['code']??'')]);sheet_reply(['history'=>$q->fetchAll()]);}
 if($action==='export'){team_require('export');$data=sheet_rows($db,$_GET);if($data['total']>10000)throw new RuntimeException('Thu hẹp bộ lọc để xuất tối đa 10.000 đơn.',400);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="thevictor-bang-don-'.gmdate('Ymd').'.csv"');$out=fopen('php://output','wb');fwrite($out,"\xEF\xBB\xBF");fputcsv($out,['STT','Tiền','Tên khách','SĐT','Địa chỉ','Sản phẩm / size','Note','Check size','Tạo đơn','Chiều cao / cân nặng','Tình trạng','Mã vận đơn','Hoàn','Mã đơn hệ thống']);$safe=static fn($v)=>preg_match('/^[\s]*[=+@-]/u',(string)$v)?"'".$v:(string)$v;for($p=1;$p<=$data['pages'];$p++){$batch=sheet_rows($db,array_merge($_GET,['page'=>$p]));foreach($batch['rows'] as $r){$values=[];foreach(['number','amount','customer','phone','address','products','note','check_size','shipping_created','measurements','status','tracking','returned','code'] as $key)$values[]=$key==='status'?ADMIN_STATUSES[$r[$key]]:$r[$key];fputcsv($out,array_map($safe,$values));}}fclose($out);exit;}
 sheet_reply(sheet_rows($db,$_GET)+['user'=>$identity,'states'=>ADMIN_STATUSES]);}
 if($method!=='POST')throw new RuntimeException('Phương thức không hỗ trợ.',405);if(($_SERVER['HTTP_ORIGIN']??'')!=='https://thevictor.vn'||!str_contains(strtolower($_SERVER['CONTENT_TYPE']??''),'application/json'))throw new RuntimeException('Nguồn yêu cầu không hợp lệ.',403);
 $raw=file_get_contents('php://input',false,null,0,1000001);if(strlen($raw)>1000000)throw new RuntimeException('Dữ liệu quá lớn. Dán ít dòng hơn.',413);$body=json_decode($raw,true,512,JSON_THROW_ON_ERROR);$_POST['csrf']=$body['csrf']??null;admin_csrf();
 if(($body['action']??'')==='user'){team_save($body);sheet_reply(['ok'=>true]);}if(($body['action']??'')!=='save')throw new RuntimeException('Thao tác không hợp lệ.',400);$db=admin_db();sheet_schema($db);sheet_reply(['ok'=>true,'saved'=>sheet_save($db,$body['changes']??[],$identity['username'])]);
}catch(Throwable $e){$status=in_array($e->getCode(),[400,401,403,404,405,409,413],true)?$e->getCode():500;if($e instanceof JsonException)$status=400;sheet_reply(['error'=>$status===500?'Chưa xử lý được yêu cầu. Vui lòng thử lại.':($e instanceof JsonException?'Dữ liệu không hợp lệ.':$e->getMessage())],$status);}
